import re

from moler.exceptions import ParsingDone, CommandFailure, CommandTimeout

from ta_moler.cmd.rtg.rtg.genericrtg import GenericRtg

__author__ = 'Michal Ernst, Marcin Usielski, Dawid Gwizdz'
__copyright__ = 'Copyright (C) 2018-2019, Nokia'
__email__ = 'michal.ernst@nokia.com, marcin.usielski@nokia.com, dawid.gwizdz@gmail.com'


class Stop(GenericRtg):
    """Stop command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None, timeout_extender=300):
        """
        Stop command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param timeout_extender: Time (in seconds) to extend timeout when first line of output appears
        :param runner: Runner to run command
        """
        super(Stop, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.ret_required = True
        self._timeout_extended = False
        self.timeout_extender = timeout_extender
        self.terminating_timeout = 0.0

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "stop"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_test_halter(line)
                self._parse_error(line)
                self._parse_all_disconnected(line)
            except ParsingDone:
                pass
        return super(Stop, self).on_new_line(line, is_full_line)

    _re_all_disconnected = re.compile(r'Connection Manager: All SECTORs and TGRs disconnected')

    def set_exception(self, exception):
        """
        Use to indicate some failure during observation.

        :param exception: Exception to set.
        :return: None
        """
        if type(exception) is CommandTimeout and len(self.current_ret) == 0 and not self._timeout_extended:
            self._is_done = False
            self.current_ret["STOPPED"] = True
            self.set_result(self.current_ret)
        else:
            super(Stop, self).set_exception(exception)

    _re_test_halter = re.compile(r"Test Halter")

    def _parse_test_halter(self, line):
        """
        Stop command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if not self._timeout_extended and self._regex_helper.search_compiled(Stop._re_test_halter, line):
            self.extend_timeout(self.timeout_extender)
            self._timeout_extended = True
            raise ParsingDone()

    def _parse_all_disconnected(self, line):
        """
        Stop command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stop._re_all_disconnected, line):
            self.current_ret["STOPPED"] = True
            raise ParsingDone

    _re_error = re.compile(r'ERROR:\s*(?P<ERROR>.*)$')

    def _parse_error(self, line):
        """
        Stop command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stop._re_error, line):
            self.current_ret["ERROR"] = self._regex_helper.group("ERROR")
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))

            raise ParsingDone


